package com.kittyplay.toddlergame

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool
import android.os.Handler
import android.os.Looper
import android.speech.tts.TextToSpeech
import java.io.File
import java.util.Locale
import java.util.concurrent.ConcurrentHashMap
import kotlin.concurrent.thread

/**
 * Plays everything the app says or sounds like. It needs no audio files: effects
 * and cartoon animal calls are generated by code, and names use the phone's voice.
 * A file with a matching name in assets/media replaces the generated version.
 */
class SoundEngine(private val context: Context) {
    var enabled = true
        set(value) {
            field = value
            if (!value) stopAll()
        }

    private val pool = SoundPool.Builder()
        .setMaxStreams(8)
        .setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_GAME)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()
        )
        .build()

    private val soundIds = ConcurrentHashMap<String, Int>()
    private val callSeconds = ConcurrentHashMap<String, Double>()
    private val handler = Handler(Looper.getMainLooper())
    private var pendingName: Runnable? = null
    private var callStream = 0
    private var purrStream = 0
    private var lastPop = 0L

    private var tts: TextToSpeech? = null
    private var ttsReady = false

    init {
        tts = TextToSpeech(context) { status ->
            if (status == TextToSpeech.SUCCESS) {
                tts?.language = Locale.forLanguageTag(Words.VOICE_LANGUAGE)
                ttsReady = true
            }
        }
        // Generating sounds takes a moment, so it happens away from the screen's thread.
        thread(name = "sound-setup") { loadAllSounds() }
    }

    private fun loadAllSounds() {
        val folder = File(context.cacheDir, "generated-sounds").apply { mkdirs() }

        fun load(name: String, make: () -> ShortArray) {
            val custom = openCustomFile(name)
            if (custom != null) {
                soundIds[name] = pool.load(custom, 1)
                custom.close()
                return
            }
            val samples = make()
            val file = File(folder, "$name.wav")
            file.writeBytes(ToneSynth.wav(samples))
            soundIds[name] = pool.load(file.path, 1)
            callSeconds[name] = samples.size.toDouble() / ToneSynth.SAMPLE_RATE
        }

        load("fx_pop") { ToneSynth.pop() }
        load("fx_boing") { ToneSynth.boing() }
        load("fx_giggle") { ToneSynth.giggle() }
        load("fx_fanfare") { ToneSynth.fanfare() }
        load("fx_purr") { ToneSynth.purr() }
        for (animal in Animal.entries) {
            load("sound_${animal.id}") { ToneSynth.animalCall(animal) }
        }
    }

    private fun openCustomFile(name: String) = listOf("m4a", "mp3", "wav", "ogg").firstNotNullOfOrNull { ext ->
        try {
            context.assets.openFd("media/$name.$ext")
        } catch (_: Exception) {
            null
        }
    }

    private fun play(name: String, volume: Float = 1f, loop: Int = 0): Int {
        if (!enabled) return 0
        val id = soundIds[name] ?: return 0
        return pool.play(id, volume, volume, 1, loop, 1f)
    }

    fun boing() = play("fx_boing", 0.7f)
    fun giggle(volume: Float = 1f) = play("fx_giggle", volume)
    fun fanfare() = play("fx_fanfare")

    /** The soft pop on every touch, limited so that mashing the screen stays pleasant. */
    fun pop() {
        val now = System.currentTimeMillis()
        if (now - lastPop < 120) return
        lastPop = now
        play("fx_pop", 0.4f)
    }

    fun startPurr() {
        if (purrStream == 0) purrStream = play("fx_purr", 1f, loop = -1)
    }

    fun stopPurr() {
        if (purrStream != 0) pool.stop(purrStream)
        purrStream = 0
    }

    fun animalCall(animal: Animal) {
        interruptVoices()
        callStream = play("sound_${animal.id}")
    }

    /** Plays the animal's call, then a voice says its name. */
    fun animalCallThenName(animal: Animal) {
        animalCall(animal)
        if (!enabled) return
        val wait = callSeconds["sound_${animal.id}"] ?: 1.5
        val sayName = Runnable { speak(animal.spokenName, pitch = 1.2f, rate = 0.85f) }
        pendingName = sayName
        handler.postDelayed(sayName, (wait * 1000).toLong() + 100)
    }

    fun say(text: String) {
        interruptVoices()
        speak(text, pitch = 1.3f, rate = 0.9f)
    }

    /** The slow, low voice for the sleepy cat screen. */
    fun sayAllDone() {
        interruptVoices()
        speak(Words.ALL_DONE, pitch = 0.85f, rate = 0.65f)
    }

    private fun speak(text: String, pitch: Float, rate: Float) {
        if (!enabled || !ttsReady) return
        tts?.setPitch(pitch)
        tts?.setSpeechRate(rate)
        tts?.speak(text, TextToSpeech.QUEUE_FLUSH, null, "kittyplay")
    }

    private fun interruptVoices() {
        pendingName?.let { handler.removeCallbacks(it) }
        pendingName = null
        if (callStream != 0) pool.stop(callStream)
        callStream = 0
        if (ttsReady) tts?.stop()
    }

    fun stopAll() {
        interruptVoices()
        stopPurr()
    }

    fun release() {
        stopAll()
        pool.release()
        tts?.shutdown()
        tts = null
    }
}
